// Python-compatible value formatting (repr / str) for the value kinds
// used by this program: str, int (BigInt), and flat dicts.

// Matches Unicode code points that Python's str.isprintable() treats as
// non-printable: Other (Cc, Cf, Cs, Co, Cn) and Separator (Zl, Zp, Zs),
// except for the ASCII space U+0020 which Python considers printable.
const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

function isPrintable(ch) {
  if (ch === ' ') return true;
  return !NON_PRINTABLE.test(ch);
}

function hexEscape(cp) {
  if (cp < 0x100) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp < 0x10000) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

// Replicates Python's repr() for str.
export function pyStrRepr(s) {
  // Python prefers single quotes, but switches to double quotes when the
  // string contains a single quote and no double quote.
  let quote = "'";
  if (s.includes("'") && !s.includes('"')) quote = '"';
  let out = quote;
  for (const ch of s) {
    if (ch === quote || ch === '\\') {
      out += '\\' + ch;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (isPrintable(ch)) {
      out += ch;
    } else {
      out += hexEscape(ch.codePointAt(0));
    }
  }
  return out + quote;
}

// Replicates Python's repr() for the supported value kinds.
export function pyRepr(value) {
  if (typeof value === 'string') return pyStrRepr(value);
  if (typeof value === 'bigint') return value.toString();
  if (typeof value === 'number') return String(value);
  if (value instanceof PyDict) return pyDictRepr(value.entries);
  throw new TypeError('pyRepr: unsupported value ' + String(value));
}

// Ordered dict container mirroring Python dict insertion order.
export class PyDict {
  constructor(entries = []) {
    this.entries = entries; // array of [key, value]
  }
  set(key, value) {
    for (const pair of this.entries) {
      if (pair[0] === key) {
        pair[1] = value;
        return;
      }
    }
    this.entries.push([key, value]);
  }
  get(key) {
    for (const pair of this.entries) {
      if (pair[0] === key) return pair[1];
    }
    return undefined;
  }
}

// Replicates Python's repr() for dict: {'k': v, ...}
export function pyDictRepr(entries) {
  const parts = entries.map(([k, v]) => pyRepr(k) + ': ' + pyRepr(v));
  return '{' + parts.join(', ') + '}';
}

// Replicates Python's repr() for list: [v1, v2, ...]
export function pyListRepr(values) {
  return '[' + values.map(pyRepr).join(', ') + ']';
}

// Replicates Python's json.dumps with default options:
// ensure_ascii=True, separators=(', ', ': ').

// Ordered dict: plain array of [key, value] pairs.
export class JsonDict {
  constructor(entries = []) {
    this.entries = entries;
  }
}

function escapeString(s) {
  let out = '"';
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '"') out += '\\"';
    else if (ch === '\\') out += '\\\\';
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (cp === 0x08) out += '\\b';
    else if (cp === 0x0c) out += '\\f';
    else if (cp < 0x20) out += '\\u' + cp.toString(16).padStart(4, '0');
    else if (cp < 0x7f) out += ch;
    else if (cp < 0x10000) out += '\\u' + cp.toString(16).padStart(4, '0');
    else {
      // ensure_ascii: astral characters become UTF-16 surrogate pairs.
      out += '\\u' + ch.charCodeAt(0).toString(16).padStart(4, '0');
      out += '\\u' + ch.charCodeAt(1).toString(16).padStart(4, '0');
    }
  }
  return out + '"';
}

// Serializes str / int (BigInt) / JsonDict exactly like json.dumps.
export function pyJsonDumps(value) {
  if (typeof value === 'string') return escapeString(value);
  if (typeof value === 'bigint') return value.toString();
  if (typeof value === 'number') return String(value);
  if (value instanceof JsonDict) {
    if (value.entries.length === 0) return '{}';
    const parts = value.entries.map(
      ([k, v]) => escapeString(k) + ': ' + pyJsonDumps(v)
    );
    return '{' + parts.join(', ') + '}';
  }
  throw new TypeError('pyJsonDumps: unsupported value ' + String(value));
}

// Replicates Python's str.splitlines(keepends=True).
// Python splits on: \n \r \r\n \v \f \x1c \x1d \x1e \x85    

const LINE_BOUNDARIES = new Set([
  '\n', '\r', '\v', '\f', '\x1c', '\x1d', '\x1e', '\x85', ' ', ' ',
]);

export function splitlinesKeepends(s) {
  const lines = [];
  let start = 0;
  let i = 0;
  while (i < s.length) {
    const ch = s[i];
    if (LINE_BOUNDARIES.has(ch)) {
      if (ch === '\r' && i + 1 < s.length && s[i + 1] === '\n') {
        i += 2;
      } else {
        i += 1;
      }
      lines.push(s.slice(start, i));
      start = i;
    } else {
      i += 1;
    }
  }
  if (start < s.length) lines.push(s.slice(start));
  return lines;
}

// Replicates Python's str.splitlines(keepends=True).
// Python splits on: \n \r \r\n \v \f \x1c \x1d \x1e \x85    

const LINE_BOUNDARIES = new Set([
  '\n', '\r', '\v', '\f', '\x1c', '\x1d', '\x1e', '\x85', ' ', ' ',
]);

export function splitlinesKeepends(s) {
