}

// Faithful port of the parts of CPython's difflib used by deepdiff:
// SequenceMatcher (with the autojunk heuristic) and unified_diff.

class SequenceMatcher {
  constructor(a, b, autojunk = true) {
    this.a = a;
    this.b = b;
    this.autojunk = autojunk;
    this._chainB();
  }

  _chainB() {
    const b = this.b;
    const b2j = new Map();
    b.forEach((elt, i) => {
      let indices = b2j.get(elt);
      if (indices === undefined) {
        indices = [];
        b2j.set(elt, indices);
      }
      indices.push(i);
    });
    // No isjunk callable is used here, so bjunk stays empty.
    this.bjunk = new Set();
    // Purge popular elements (autojunk heuristic).
    this.bpopular = new Set();
    const n = b.length;
    if (this.autojunk && n >= 200) {
      const ntest = Math.floor(n / 100) + 1;
      for (const [elt, idxs] of b2j) {
        if (idxs.length > ntest) {
          this.bpopular.add(elt);
          b2j.delete(elt);
        }
      }
    }
    this.b2j = b2j;
    this.matchingBlocks = null;
  }

  findLongestMatch(alo, ahi, blo, bhi) {
    const { a, b2j } = this;
    const b = this.b;
    const isbjunk = (x) => this.bjunk.has(x);
    let besti = alo;
    let bestj = blo;
    let bestsize = 0;
    let j2len = new Map();
    for (let i = alo; i < ahi; i++) {
      const newj2len = new Map();
      const indices = b2j.get(a[i]) || [];
      for (const j of indices) {
        if (j < blo) continue;
        if (j >= bhi) break;
        const k = (j2len.get(j - 1) || 0) + 1;
        newj2len.set(j, k);
        if (k > bestsize) {
          besti = i - k + 1;
          bestj = j - k + 1;
          bestsize = k;
        }
      }
      j2len = newj2len;
    }
    // Extend the best match by non-junk on each side.
    while (
      besti > alo && bestj > blo &&
      !isbjunk(b[bestj - 1]) && a[besti - 1] === b[bestj - 1]
    ) {
      besti -= 1; bestj -= 1; bestsize += 1;
    }
    while (
      besti + bestsize < ahi && bestj + bestsize < bhi &&
      !isbjunk(b[bestj + bestsize]) && a[besti + bestsize] === b[bestj + bestsize]
    ) {
      bestsize += 1;
    }
    // Extend over junk (bjunk is always empty here, kept for fidelity).
    while (
      besti > alo && bestj > blo &&
      isbjunk(b[bestj - 1]) && a[besti - 1] === b[bestj - 1]
    ) {
      besti -= 1; bestj -= 1; bestsize += 1;
    }
    while (
      besti + bestsize < ahi && bestj + bestsize < bhi &&
      isbjunk(b[bestj + bestsize]) && a[besti + bestsize] === b[bestj + bestsize]
    ) {
      bestsize += 1;
    }
    return [besti, bestj, bestsize];
  }

  getMatchingBlocks() {
    if (this.matchingBlocks !== null) return this.matchingBlocks;
    const la = this.a.length;
    const lb = this.b.length;
    const queue = [[0, la, 0, lb]];
    const matchingBlocks = [];
    while (queue.length > 0) {
      const [alo, ahi, blo, bhi] = queue.pop();
      const [i, j, k] = this.findLongestMatch(alo, ahi, blo, bhi);
      if (k > 0) {
        matchingBlocks.push([i, j, k]);
        if (alo < i && blo < j) queue.push([alo, i, blo, j]);
        if (i + k < ahi && j + k < bhi) queue.push([i + k, ahi, j + k, bhi]);
      }
    }
    matchingBlocks.sort((x, y) => x[0] - y[0] || x[1] - y[1]);
    // Collapse adjacent matching blocks.
    let i1 = 0, j1 = 0, k1 = 0;
    const nonAdjacent = [];
    for (const [i2, j2, k2] of matchingBlocks) {
      if (i1 + k1 === i2 && j1 + k1 === j2) {
        k1 += k2;
      } else {
        if (k1 > 0) nonAdjacent.push([i1, j1, k1]);
        i1 = i2; j1 = j2; k1 = k2;
      }
    }
    if (k1 > 0) nonAdjacent.push([i1, j1, k1]);
    nonAdjacent.push([la, lb, 0]);
    this.matchingBlocks = nonAdjacent;
    return nonAdjacent;
  }

  getOpcodes() {
    const answer = [];
    let i = 0, j = 0;
    for (const [ai, bj, size] of this.getMatchingBlocks()) {
      let tag = '';
      if (i < ai && j < bj) tag = 'replace';
      else if (i < ai) tag = 'delete';
      else if (j < bj) tag = 'insert';
      if (tag) answer.push([tag, i, ai, j, bj]);
      i = ai + size;
      j = bj + size;
      if (size > 0) answer.push(['equal', ai, i, bj, j]);
    }
    return answer;
  }

  getGroupedOpcodes(n = 3) {
    let codes = this.getOpcodes();
    if (codes.length === 0) codes = [['equal', 0, 1, 0, 1]];
    // Fixup leading and trailing groups if they show no changes.
    if (codes[0][0] === 'equal') {
      const [tag, i1, i2, j1, j2] = codes[0];
      codes[0] = [tag, Math.max(i1, i2 - n), i2, Math.max(j1, j2 - n), j2];
    }
    if (codes[codes.length - 1][0] === 'equal') {
      const [tag, i1, i2, j1, j2] = codes[codes.length - 1];
      codes[codes.length - 1] = [tag, i1, Math.min(i2, i1 + n), j1, Math.min(j2, j1 + n)];
    }
    const nn = n + n;
    const groups = [];
    let group = [];
    for (const [tag, i1, i2, j1, j2] of codes) {
      // End the current group and start a new one whenever
      // there is a large range with no changes.
      if (tag === 'equal' && i2 - i1 > nn) {
        group.push([tag, i1, Math.min(i2, i1 + n), j1, Math.min(j2, j1 + n)]);
        groups.push(group);
        group = [[tag, Math.max(i1, i2 - n), i2, Math.max(j1, j2 - n), j2]];
        continue;
      }
      group.push([tag, i1, i2, j1, j2]);
    }
    if (group.length > 0 && !(group.length === 1 && group[0][0] === 'equal')) {
      groups.push(group);
    }
    return groups;
  }
}

function formatRangeUnified(start, stop) {
  let beginning = start + 1;
  const length = stop - start;
  if (length === 1) return String(beginning);
  if (length === 0) beginning -= 1; // empty ranges begin at line just before
  return beginning + ',' + length;
}

// Port of difflib.unified_diff with default fromfile/tofile/dates,
// n=3 and lineterm='\n'. Yields lines (content lines keep their
// original terminators when a/b come from splitlines(keepends=True)).
export function* unifiedDiff(a, b, n = 3, lineterm = '\n') {
  const sm = new SequenceMatcher(a, b);
  let started = false;
  for (const group of sm.getGroupedOpcodes(n)) {
    if (!started) {
      started = true;
      yield '--- ' + lineterm;
      yield '+++ ' + lineterm;
    }
    const first = group[0];
    const last = group[group.length - 1];
    const file1Range = formatRangeUnified(first[1], last[2]);
    const file2Range = formatRangeUnified(first[3], last[4]);
    yield '@@ -' + file1Range + ' +' + file2Range + ' @@' + lineterm;
    for (const [tag, i1, i2, j1, j2] of group) {
      if (tag === 'equal') {
        for (let i = i1; i < i2; i++) yield ' ' + a[i];
        continue;
      }
      if (tag === 'replace' || tag === 'delete') {
        for (let i = i1; i < i2; i++) yield '-' + a[i];
      }
      if (tag === 'replace' || tag === 'insert') {
        for (let j = j1; j < j2; j++) yield '+' + b[j];
      }
    }
  }
}

// The combined helper deepdiff uses for multiline string diffs:
// ''.join(difflib.unified_diff(t1.splitlines(keepends=True),
//                              t2.splitlines(keepends=True)))
export function stringsUnifiedDiff(t1Lines, t2Lines) {
  return [...unifiedDiff(t1Lines, t2Lines)].join('');
}

// Minimal black-box reimplementation of deepdiff's DeepDiff and Delta,
// covering the behavior exercised by this program: flat dicts whose
// values are str or int.

import { pyStrRepr, pyRepr, pyListRepr } from './pyformat.mjs';
import { JsonDict, pyJsonDumps } from './pyjson.mjs';
import { splitlinesKeepends } from './pystr.mjs';
import { stringsUnifiedDiff } from './difflib.mjs';

function valuesEqual(v1, v2) {
  return typeof v1 === typeof v2 && v1 === v2;
}

export class DeepDiff {
  // t1/t2 are PyDict-like: arrays of [key, value] entries in insertion order.
  constructor(t1, t2) {
    // Ordered list of [category, data]. Category order follows deepdiff's
    // reporting order: dictionary_item_added, dictionary_item_removed,
    // then values_changed.
    this.results = [];
    this._diffDict(t1, t2);
  }

  _report(category, data) {
    let entry = this.results.find(([c]) => c === category);
    if (!entry) {
      entry = [category, []];
      this.results.push(entry);
    }
    entry[1].push(data);
  }

