// Minimal reimplementation of the Python argparse behavior used by the
// original script: three required options --a (str), --b (int), --c (int),
// plus -h/--help. Error/usage formats and exit codes mirror argparse.

import { pyStrRepr } from './pyformat.mjs';

const OPTIONS = [
  { names: ['--a'], dest: 'a', metavar: 'A', type: 'str', required: true },
  { names: ['--b'], dest: 'b', metavar: 'B', type: 'int', required: true },
  { names: ['--c'], dest: 'c', metavar: 'C', type: 'int', required: true },
];
const LONG_NAMES = ['--help', '--a', '--b', '--c'];

// argparse's _negative_number_matcher; since no option strings look like
// negative numbers, tokens matching this are treated as values.
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function usageLine(prog) {
  return `usage: ${prog} [-h] --a A --b B --c C`;
}

function printHelp(prog) {
  const lines = [
    usageLine(prog),
    '',
    'options:',
    '  -h, --help  show this help message and exit',
    '  --a A',
    '  --b B',
    '  --c C',
  ];
  process.stdout.write(lines.join('\n') + '\n');
}

function error(prog, message) {
  process.stderr.write(usageLine(prog) + '\n');
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

// Replicates Python's int(str): strips surrounding whitespace, allows a
// sign and single underscores between digits. Returns a BigInt so that
// arbitrarily large integers keep full precision like Python ints.
function parseIntValue(s) {
  const stripped = s.trim();
  if (!/^[+-]?\d+(_\d+)*$/.test(stripped)) return null;
  return BigInt(stripped.replace(/_/g, ''));
}

function isOptionLike(token) {
  if (!token.startsWith('-')) return false;
  if (token === '-') return false;
  if (NEGATIVE_NUMBER.test(token)) return false;
  return true;
}

function resolveLongOption(prog, name) {
  if (LONG_NAMES.includes(name)) return name;
  const matches = LONG_NAMES.filter((n) => n.startsWith(name));
  if (matches.length === 1) return matches[0];
  if (matches.length > 1) {
    error(prog, `ambiguous option: ${name} could match ${matches.join(', ')}`);
  }
  return null;
}

export function parseArgs(argv) {
  const prog = (argv[1] || '').split('/').pop() || 'test15.mjs';
  const tokens = argv.slice(2);
  const values = {};
  const extras = [];

  let i = 0;
  while (i < tokens.length) {
    const token = tokens[i];
    if (token === '--') {
      // Everything after '--' is positional; this script has none.
      extras.push(...tokens.slice(i + 1));
      break;
    }
    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      const name = eq === -1 ? token : token.slice(0, eq);
      const inlineValue = eq === -1 ? null : token.slice(eq + 1);
      const resolved = resolveLongOption(prog, name);
      if (resolved === null) {
        extras.push(token);
        i += 1;
        continue;
      }
      if (resolved === '--help') {
        printHelp(prog);
        process.exit(0);
      }
      const opt = OPTIONS.find((o) => o.names.includes(resolved));
      let value;
      if (inlineValue !== null) {
        value = inlineValue;
      } else if (i + 1 < tokens.length && !isOptionLike(tokens[i + 1])) {
        value = tokens[i + 1];
        i += 1;
      } else {
        error(prog, `argument ${resolved}: expected one argument`);
      }
      if (opt.type === 'int') {
        const parsed = parseIntValue(value);
        if (parsed === null) {
          error(prog, `argument ${resolved}: invalid int value: ${pyStrRepr(value)}`);
        }
        values[opt.dest] = parsed;
      } else {
        values[opt.dest] = value;
      }
      i += 1;
      continue;
    }
    if (token === '-h') {
      printHelp(prog);
      process.exit(0);
    }
    extras.push(token);
    i += 1;
  }

  const missing = OPTIONS.filter((o) => o.required && !(o.dest in values))
    .map((o) => o.names[0]);
  if (missing.length > 0) {
    error(prog, `the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length > 0) {
    error(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }
  return values;
}

